style.css:
@-moz-document domain("youtube.com") {
body, ytd-app {
        background-image: url('https://i.postimg.cc/PxHsg2kC/Mizusua.gif') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    #cinematic-container, 
    ytd-cinematic-container-renderer,
    div#cinematic-container {
        display: none !important;
    }

#columns, 
    #content, 
    ytd-masthead,
    #page-manager,
    ytd-page-manager,
    ytd-watch-flexy,
    ytd-watch-flexy[flexy],
    ytd-watch-flexy[cinema],
    #primary, 
    #primary-inner,
    #secondary,
    #secondary-inner,
    #player-container-outer, 
    #player-container-inner, 
    #player-container,
    #player-full-bleed-container,
    #full-bleed-container,
    #player,
    #ytd-player,
    div#container.ytd-player {
        background: transparent !important;
        background-color: transparent !important;
    }

    tp-yt-app-drawer, 
    ytd-guide-renderer, 
    ytd-mini-guide-renderer,
    #guide-content {
        background: rgba(15, 15, 15, 0.3) !important;
        z-index: 9999 !important;
    }

    ytd-masthead {
        background: rgba(0, 0, 0, 0.3) !important;
    }

    ytd-rich-item-renderer, 
    ytd-compact-video-renderer, 
    ytd-video-renderer, 
    ytd-playlist-renderer {
        background: rgba(0, 0, 0, 0.5) !important;
        border-radius: 20px !important;
        padding: 10px !important;
        box-sizing: border-box !important;
    }

   #comments, 
    ytd-comments, 
    ytd-watch-metadata #description {
        background: rgba(0, 0, 0, 0.5) !important;
        border-radius: 12px !important;
        padding: 13px !important;
        margin-top: 10px !important;
    }

    #video-title, 
    #byline, 
    #metadata-line, 
    #description-text,
    #content-text, 
    #author-text, 
    ytd-guide-entry-renderer *,
    ytd-comment-view-model *,
    ytd-comment-thread-renderer * {
        color: #ffffff !important;
    }
}
